<?php
session_start();
$db = new PDO('sqlite:' . __DIR__ . '/iro.sqlite');
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
$db->exec('CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT UNIQUE, role TEXT, community TEXT, category TEXT, description TEXT, status TEXT DEFAULT "Pending", created_at TEXT DEFAULT CURRENT_TIMESTAMP)');
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(16));
$notice = ''; $result = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 if (!hash_equals($_SESSION['csrf'], $_POST['csrf'] ?? '')) { $notice = 'Invalid form session. Please try again.'; }
 elseif (($_POST['action'] ?? '') === 'submit') {
  $role=trim($_POST['role']??''); $community=trim($_POST['community']??''); $category=trim($_POST['category']??''); $description=trim($_POST['description']??'');
  if (!in_array($role,['Student','Indigene','Resident'],true) || !in_array($community,['Akungba','Iwaro','Etioro','Ayegunle','Other'],true) || !in_array($category,['Security','Accommodation','Sanitation','Infrastructure','Harassment','Other'],true) || mb_strlen($description)<15 || mb_strlen($description)>2000) $notice='Please complete all fields. Description must be 15 to 2000 characters.';
  else { $ref='IRO-'.strtoupper(bin2hex(random_bytes(4))); $stmt=$db->prepare('INSERT INTO reports(reference,role,community,category,description) VALUES(?,?,?,?,?)'); $stmt->execute([$ref,$role,$community,$category,$description]); $notice='Report submitted. Save your tracking reference: '.$ref; }
 } elseif (($_POST['action']??'')==='track') {
  $ref=strtoupper(trim($_POST['reference']??'')); $stmt=$db->prepare('SELECT reference,category,community,status,created_at FROM reports WHERE reference=?'); $stmt->execute([$ref]); $result=$stmt->fetch(PDO::FETCH_ASSOC); if (!$result) $notice='No report found for that reference.';
 }
}
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
?>
