<section class="soft section" id="report"><div class="container split"><div><span class="eyebrow">Speak up</span><h2>Report an issue</h2><p>Describe an issue affecting your community. Please avoid including names, phone numbers, or other identifying details.</p><div class="hint"><strong>Emergency?</strong><p>This is a demonstration project, not an emergency response service. Contact local emergency services or the appropriate authorities if someone is in immediate danger.</p></div></div><div class="panel"><h3>New issue report</h3><?php if ($notice): ?><div class="notice" role="status"><?=e($notice)?></div><?php endif; ?><form method="post" action="#report"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="submit"><label>Your role<select name="role" required><option value="">Select your role</option><option>Student</option><option>Indigene</option><option>Resident</option></select></label><label>Community<select name="community" required><option value="">Select community</option><option>Akungba</option><option>Iwaro</option><option>Etioro</option><option>Ayegunle</option><option>Other</option></select></label><label>Issue category<select name="category" required><option value="">Select category</option><option>Security</option><option>Accommodation</option><option>Sanitation</option><option>Infrastructure</option><option>Harassment</option><option>Other</option></select></label><label>Describe the issue<textarea name="description" minlength="15" maxlength="2000" rows="5" placeholder="What happened? Where? What needs attention?" required></textarea></label><button class="btn full" type="submit">Submit issue →</button></form></div></div></section>
<section class="container section" id="track"><div class="track-wrap"><div><span class="eyebrow">Stay informed</span><h2>Track your report</h2><p>Enter the reference you received after submission to view the current status.</p></div><div class="panel"><form method="post" action="#track"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="track"><label>Tracking reference<input name="reference" placeholder="IRO-XXXXXXXX" pattern="IRO-[A-Fa-f0-9]{8}" required></label><button class="btn full" type="submit">Check status</button></form><?php if ($result): ?><div class="result"><strong><?=e($result['reference'])?></strong><p><?=e($result['category'])?> · <?=e($result['community'])?></p><span class="status"><?=e($result['status'])?></span><p class="small">Submitted: <?=e($result['created_at'])?> (server time)</p></div><?php elseif (($_POST['action']??'')==='track' && $notice): ?><div class="notice" role="status"><?=e($notice)?></div><?php endif; ?></div></div></section></main><footer><div class="container footer"><strong>IRO <span>Issues Reporting Outlet</span></strong><span>AAUA & Host Communities · Academic demonstration</span></div></footer></body></html>
